                    mainAxisSize: MainAxisSize.min,
                    children: [
                      EasyTextWidget(
                        text: 'စာအုပ်မိတ်ဆက် ${index + 1}',
                        fontWeight: FontWeight.w600,
                      ),
                      const SizedBox(
                        height: kSP20x,
                      ),
                      EasyTextWidget(
                        text: pageList[index],
                        maxLines: 100,
                      ),
                    ],
                  ),
                ),
              ),
            ),
            const SizedBox(
              height: kSP20x,
            ),
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                IconButton(
                  icon: Icon(
                    Icons.arrow_circle_left,
                  ),
                  onPressed: () {
                    if (_index > 0) {
                      if (mounted) {
                        setState(() {
                          _index = _index - 1;
                          _pageController.jumpToPage(_index);
                        });
                      }
                    }
                  },
                ),
                const SizedBox(
                  width: kSP10x,
                ),
                EasyTextWidget(
                  text: '${_index + 1} of ${pageList.length}',
                  fontWeight: FontWeight.w600,
                ),
                const SizedBox(
                  width: kSP10x,
                ),
                IconButton(
                  icon: Icon(
                    Icons.arrow_circle_right,
                  ),
                  onPressed: () {
                    if (_index < pageList.length - 1) {
                      if (mounted) {
                        setState(() {
                          _index = _index + 1;
                          _pageController.jumpToPage(_index);
                        });
                      }
                    }
                  },
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

